//! 🧪️ A genuine original owner lends virtual final fields without creating a candidate Snapshot.
use super::*;
use crate::validation::retained::LayoutValidationCursor;
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneGrant};
#[derive(semio_framework_value::RetireOwned)]struct VirtualOwner{live:LayoutSnapshot,authored:Frame}
macro_rules! delegate{($($name:ident($($arg:ident:$kind:ty),*)->$result:ty;)+)=>{$(fn $name(&self,$($arg:$kind),*)->$result{self.live.$name($($arg),*)})+};}
impl LayoutGraphRead for VirtualOwner{
 delegate!{schema()->&str;grid()->GridRead;paragraph_count()->usize;paragraph(row:usize)->ParagraphRead<'_>;character_count()->usize;character(row:usize)->CharacterRead<'_>;story_count()->usize;story(row:usize)->StoryRead<'_>;run_count(story:usize)->usize;run(story:usize,row:usize)->&TextStyleRun;link_count()->usize;link_id(row:usize)->&str;parent_count()->usize;parent(row:usize)->ParentRead<'_>;spread_count()->usize;spread(row:usize)->SpreadRead<'_>;spread_page_count(spread:usize)->usize;spread_page(spread:usize,row:usize)->&str;page_count()->usize;page(row:usize)->PageRead<'_>;guide_count(page:usize)->usize;guide(page:usize,row:usize)->&LayoutRect;layer_count(owner:ContentOwner)->usize;layer_id(owner:ContentOwner,row:usize)->&str;cached_layer_count(owner:ContentOwner)->usize;cached_layer(owner:ContentOwner,row:usize)->&str;override_count(page:usize)->usize;page_override(page:usize,row:usize)->OverrideRead<'_>;drawing(source:DrawingSourceAddress)->Option<&LayoutDrawingMember>;}
 fn frame_count(&self,owner:ContentOwner)->usize{self.live.frame_count(owner)+usize::from(owner==ContentOwner::Page(0))}
 fn frame(&self,owner:ContentOwner,row:usize)->FrameRead<'_>{if owner==ContentOwner::Page(0)&&row==self.live.frame_count(owner){(&self.authored).into()}else{self.live.frame(owner,row)}}
 fn member_count(&self,owner:ContentOwner,layer:usize)->usize{self.live.member_count(owner,layer)+usize::from(owner==ContentOwner::Page(0)&&layer==0)}
 fn member(&self,owner:ContentOwner,layer:usize,row:usize)->&str{if owner==ContentOwner::Page(0)&&layer==0&&row==self.live.member_count(owner,layer){self.authored.id()}else{self.live.member(owner,layer,row)}}
}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:128}}
#[test]fn virtual_final_thread_predecessor_is_checked_through_the_same_original_graph_program(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();let live:LayoutSnapshot=semio_framework_pack_json::from_json_str(&fixture["base"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut authored=live.pages[0].frames[0].clone();if let Frame::Text{id,thread_next,..}=&mut authored{*id="text-3".into();*thread_next=Some("text-2".into());}let mut oracle=live.clone();oracle.pages[0].layers[0].object_ids.push(authored.id().into());oracle.pages[0].frames.push(authored.clone());assert!(crate::validation::validate_document(&oracle).is_err());let(mut source,_)=RetainedCloneSource::admit_owned(VirtualOwner{live,authored},(),grant()).unwrap_or_else(|_|panic!("genuine virtual original owner"));let view=source.borrow();assert!(std::ptr::eq(view.get().frame(ContentOwner::Page(0),2).bounds,view.get().authored.bounds()));assert!(std::ptr::eq(view.get().run(0,0),&view.get().live.stories[0].style_runs[0]));let mut cursor=LayoutValidationCursor::new();let mut capacity=0;let mut done=false;for _ in 0..100000{assert_eq!(cursor.advance(source.borrow(),0,Default::default()).unwrap().progress,Default::default());let turn=cursor.advance(source.borrow(),grant().maximum_copy_bytes,grant()).unwrap();assert!(turn.progress.fits(grant()));capacity+=turn.progress.retained_capacity_bytes;if turn.done{assert_eq!(turn.error,Some("Text frames must have at most one predecessor."));done=true;break}}assert!(done);cursor.begin_close();let mut released=0;while !cursor.terminal_is_empty(){released+=cursor.close_step(grant()).unwrap().progress().released_bytes;}assert_eq!(released,capacity);while !source.terminal_is_empty(){source.close_step(grant()).unwrap();}}
